                  <td style="padding: 6px 12px; font-weight: bold; color: #0f172a; text-align: ${isArabic ? 'left' : 'right'}; font-family: monospace;">${quote.vat.toLocaleString(undefined, { minimumFractionDigits: 2 })} SAR</td>
