  const [selectedVisitForQuote, setSelectedVisitForQuote] = useState<Visit | null>(null);
  const [selectedClientForQuote, setSelectedClientForQuote] = useState<Client | null>(null);
  const [isIndependentQuote, setIsIndependentQuote] = useState(false);
  const [selectedBranchName, setSelectedBranchName] = useState('');
  
  const [quoteDate, setQuoteDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [quoteItems, setQuoteItems] = useState<QuotationItem[]>([]);
  
  const [newItemDesc, setNewItemDesc] = useState('');
  const [newItemPrice, setNewItemPrice] = useState<number>(0);
  const [newItemQty, setNewItemQty] = useState<number>(1);
  const [newItemWarranty, setNewItemWarranty] = useState('');

  const [quoteTerms, setQuoteTerms] = useState<string>('');
  const [editingQuotationId, setEditingQuotationId] = useState<string | null>(null);
  const [quoteStatus, setQuoteStatus] = useState<QuotationStatus>('pending');
  const [quoteDiscountType, setQuoteDiscountType] = useState<'percentage' | 'amount'>('percentage');
  const [quoteDiscountValue, setQuoteDiscountValue] = useState<number>(0);

  const DEFAULT_TERMS = `يسري هذا العرض لمدة خمسة عشر (15) يوماً من تاريخ التحرير.
الأسعار المدرجة أعلاه خاضعة لضريبة القيمة المضافة الإلزامية بنسبة 15%.
ساعات وأجور العمل والتركيب والبرمجة مشمولة في الأسعار إلا إذا ذكر خلاف ذلك.`;

  const handleOpenCreateQuoteForVisit = (visit: Visit) => {
    const client = clients.find(c => c.id === visit.clientId);
    setSelectedVisitForQuote(visit);
    setSelectedClientForQuote(client || null);
    setIsIndependentQuote(false);
    setSelectedBranchName(visit.branchName || '');
    setQuoteDate(new Date().toISOString().split('T')[0]);
    setQuoteTerms(DEFAULT_TERMS);
    setEditingQuotationId(null);
    setQuoteStatus('pending');
    setQuoteDiscountType('percentage');
    setQuoteDiscountValue(0);
    
    // Attempt to pre-fill an item from the technician's findings
    const techNotes = visit.defects || '';
    if (techNotes.trim()) {
      setQuoteItems([
        {
          id: `item_${Date.now()}_0`,
          description: techNotes,
          unitPrice: 0,
          quantity: 1,
          totalPrice: 0,
          warranty: ''
        }
      ]);
    } else {
      setQuoteItems([]);
    }
    
    setNewItemDesc('');
    setNewItemPrice(0);
    setNewItemQty(1);
    setNewItemWarranty('');
    setShowCreateQuoteModal(true);
  };

  const handleOpenCreateIndependentQuote = () => {
    setSelectedVisitForQuote(null);
    setSelectedClientForQuote(null);
    setIsIndependentQuote(true);
    setSelectedBranchName('');
    setQuoteDate(new Date().toISOString().split('T')[0]);
    setQuoteTerms(DEFAULT_TERMS);
    setEditingQuotationId(null);
    setQuoteStatus('pending');
    setQuoteDiscountType('percentage');
    setQuoteDiscountValue(0);
    setQuoteItems([]);
    
    setNewItemDesc('');
    setNewItemPrice(0);
    setNewItemQty(1);
    setNewItemWarranty('');
    setShowCreateQuoteModal(true);
  };

  const handleOpenEditQuote = (q: Quotation) => {
    const client = clients.find(c => c.id === q.clientId);
    const visit = visits.find(v => v.id === q.visitId);
    
    setSelectedVisitForQuote(visit || null);
    setSelectedClientForQuote(client || null);
    setIsIndependentQuote(!q.visitId);
    setSelectedBranchName(q.branchName || '');
    setQuoteDate(q.date);
    setQuoteItems(q.items);
    setQuoteTerms(q.terms || '');
    setQuoteStatus(q.status);
    setQuoteDiscountType(q.discountType || 'percentage');
    setQuoteDiscountValue(q.discountValue || 0);
    setEditingQuotationId(q.id);
    
    setNewItemDesc('');
    setNewItemPrice(0);
    setNewItemQty(1);
    setNewItemWarranty('');
    setShowCreateQuoteModal(true);
  };

  const handleAddQuoteItem = () => {
    if (!newItemDesc.trim() || newItemQty <= 0) return;
    const price = newItemPrice || 0;
    const qty = newItemQty || 1;
    const newItem: QuotationItem = {
      id: `item_${Date.now()}`,
      description: newItemDesc,
      unitPrice: price,
      quantity: qty,
      totalPrice: price * qty,
      warranty: newItemWarranty
    };
    setQuoteItems(prev => [...prev, newItem]);
    setNewItemDesc('');
    setNewItemPrice(0);
    setNewItemQty(1);
    setNewItemWarranty('');
  };

  const handleRemoveQuoteItem = (itemId: string) => {
    setQuoteItems(prev => prev.filter(item => item.id !== itemId));
  };

  const handlePrintWorkOrder = (quote: Quotation) => {
    const isArabic = isRtl;
    const clientObj = clients.find(c => c.id === quote.clientId);
    const techObj = technicians.find(t => t.id === quote.assignedTechId);
    const assignedTechName = quote.assignedTechName || techObj?.name || (isArabic ? 'بانتظار توجيه فني' : 'Unassigned');
    const assignedTechPhone = techObj?.phone || '';
    const clientAddress = quote.clientNationalAddress || clientObj?.nationalAddress || clientObj?.locationText || (isArabic ? 'المملكة العربية السعودية' : 'Saudi Arabia');
    const clientPhone = clientObj?.phone || '';
    const branchName = quote.branchName || clientObj?.branches?.[0]?.name || (isArabic ? 'الفرع الرئيسي' : 'Main Branch');

    // Official company details from Personal Profile / Settings (Unified No. & Tax No. only, without Civil Defense License)
    const compName = customization?.companyName || companyName || (isArabic ? 'شركة نسما الأولى لأنظمة السلامة' : 'Nesma First Safety Systems');
    const compUnified = customization?.unifiedNumber || companyUnifiedNumber || localStorage.getItem('sas_company_unified_number') || '7003489890';
    const compTax = customization?.companyTaxNumber || companyTaxNumber || localStorage.getItem('sas_company_tax_number') || '310456789000003';

    // Work order assignment & issue date (actual date directed to the technician, NOT the quote creation date)
    const issueAndAssignmentDate = quote.workOrderAssignedDate 
      || (quote.assignedTechId ? (quote.executionReport?.completedAt?.split('T')[0] || new Date().toISOString().split('T')[0]) : new Date().toISOString().split('T')[0]);

    const statusLabel = 
      quote.workOrderStatus === 'completed' ? (isArabic ? 'منجز ومكتمل' : 'Completed') :
      quote.workOrderStatus === 'partially_completed' ? (isArabic ? 'منجز جزئياً' : 'Partially Completed') :
      quote.workOrderStatus === 'pending' ? (isArabic ? 'قيد التنفيذ الميداني' : 'In Progress') :
      (isArabic ? 'أمر عمل جديد' : 'New Order');

    const statusBg = 
      quote.workOrderStatus === 'completed' ? '#d1fae5' :
      quote.workOrderStatus === 'partially_completed' ? '#ffedd5' :
      quote.workOrderStatus === 'pending' ? '#fef3c7' : '#e0f2fe';

    const statusColor = 
      quote.workOrderStatus === 'completed' ? '#047857' :
      quote.workOrderStatus === 'partially_completed' ? '#c2410c' :
      quote.workOrderStatus === 'pending' ? '#b45309' : '#0369a1';

    const itemsRowsHtml = quote.items.map((item, idx) => {
      const isItemDone = quote.executionReport?.completedItems?.includes(item.id);
      return `
        <tr>
          <td style="padding: 9px 8px; border: 1px solid #cbd5e1; text-align: center; font-weight: bold; font-family: monospace; font-size: 11px;">
            ${idx + 1}
          </td>
          <td style="padding: 9px 12px; border: 1px solid #cbd5e1; text-align: ${isArabic ? 'right' : 'left'}; font-size: 11px;">
            <strong style="color: #0f172a; font-size: 11.5px; display: block;">${item.description}</strong>
            ${item.warranty ? `<span style="font-size: 9.5px; color: #0f766e; font-weight: bold; display: block; margin-top: 3px;">${isArabic ? 'الضمان:' : 'Warranty:'} ${item.warranty}</span>` : ''}
          </td>
          <td style="padding: 9px 8px; border: 1px solid #cbd5e1; text-align: center; font-weight: bold; font-family: monospace; font-size: 12px;">
            ${item.quantity}
          </td>
          <td style="padding: 9px 8px; border: 1px solid #cbd5e1; text-align: center; font-size: 10px;">
            ${item.warranty ? item.warranty : (isArabic ? 'ساري بموجب الشروط' : 'Standard')}
          </td>
          <td style="padding: 9px 8px; border: 1px solid #cbd5e1; text-align: center; font-size: 10.5px;">
            ${isItemDone 
              ? `<span style="color: #047857; font-weight: bold;">☑ ${isArabic ? 'تم الإنجاز' : 'Done'}</span>` 
              : `<span style="color: #64748b;">☐ ${isArabic ? 'جاهز للتنفيذ' : 'Pending'}</span>`}
          </td>
        </tr>
      `;
    }).join('');

    // Specific operational/field notes without quote validity terms
    const specialNotes = [
      quote.clientNote ? `${isArabic ? 'ملاحظة العميل:' : 'Client Note:'} ${quote.clientNote}` : '',
      quote.executionReport?.notes ? `${isArabic ? 'ملاحظات الفني الميدانية:' : 'Tech Notes:'} ${quote.executionReport.notes}` : ''
    ].filter(Boolean).map(n => `<li>${n}</li>`).join('');

    const html = `
      <!DOCTYPE html>
      <html dir="${isArabic ? 'rtl' : 'ltr'}" lang="${isArabic ? 'ar' : 'en'}">
      <head>
        <meta charset="utf-8">
        <title>${isArabic ? 'أمر عمل' : 'Work Order'} - #${quote.id.split('_')[1] || quote.id}</title>
        <link rel="preconnect" href="https://fonts.googleapis.com">
        <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
        <link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
        <style>
          @page {
            size: A4 portrait;
            margin: 0mm !important;
          }
          @media print {
            @page {
              size: A4 portrait;
              margin: 0mm !important;
            }
            body {
              padding: 14mm 16mm !important;
              -webkit-print-color-adjust: exact !important;
              print-color-adjust: exact !important;
            }
            a[href]:after {
              content: none !important;
            }
          }
          * {
            box-sizing: border-box;
          }
          body {
            font-family: 'Cairo', 'Inter', sans-serif;
            background: #ffffff;
            color: #0f172a;
            padding: 14mm 16mm;
            margin: 0;
            font-size: 11px;
            line-height: 1.45;
          }
          .header-table {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 14px;
            border-bottom: 2.5px solid #0f766e;
            padding-bottom: 10px;
          }
          .logo {
            height: 52px;
            max-width: 130px;
            object-fit: contain;
          }
          .company-title {
            font-size: 14.5px;
            font-weight: 900;
            color: #0f172a;
            margin: 0;
          }
          .company-sub {
            font-size: 10px;
            font-weight: 700;
            color: #334155;
            margin-top: 4px;
          }
          .order-title-box {
            background: #f8fafc;
            border: 2px solid #0f766e;
            border-radius: 8px;
            padding: 6px 14px;
            text-align: center;
            display: inline-block;
          }
          .order-title-ar {
            font-size: 17px;
            font-weight: 900;
            color: #0f766e;
            line-height: 1.2;
          }
          .order-title-en {
            font-size: 9.5px;
            font-weight: 800;
            color: #64748b;
            letter-spacing: 1px;
            text-transform: uppercase;
          }
          .order-meta-table {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 14px;
            background: #f8fafc;
            border: 1px solid #cbd5e1;
            border-radius: 8px;
            overflow: hidden;
          }
          .order-meta-table td {
            padding: 8px 12px;
            vertical-align: top;
            border: 1px solid #e2e8f0;
          }
          .meta-label {
            font-size: 8.5px;
            font-weight: 700;
            color: #64748b;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            margin-bottom: 2px;
          }
          .meta-value {
            font-size: 11px;
            font-weight: 700;
            color: #0f172a;
          }
          .badge {
            display: inline-block;
            padding: 2px 8px;
            border-radius: 9999px;
            font-size: 9.5px;
            font-weight: 800;
          }
          .section-heading {
            font-size: 11px;
            font-weight: 800;
            color: #0f172a;
            margin: 12px 0 6px 0;
            padding-bottom: 3px;
            border-bottom: 1.5px solid #e2e8f0;
          }
          .tasks-table {
            width: 100%;
            border-collapse: collapse;
            margin-bottom: 12px;
          }
          .tasks-table th {
            background: #0f766e;
            color: #ffffff;
            font-weight: 800;
            padding: 7px 8px;
            font-size: 10px;
            border: 1px solid #0f766e;
          }
          .instructions-box {
            background: #f8fafc;
            border: 1px solid #cbd5e1;
            border-radius: 8px;
            padding: 8px 12px;
            margin-bottom: 14px;
          }
          .instructions-box ul {
            margin: 2px 0 0 0;
            padding-${isArabic ? 'right' : 'left'}: 16px;
            font-size: 9.5px;
            color: #334155;
            line-height: 1.55;
          }
          .signatures-table {
            width: 100%;
            border-collapse: collapse;
            margin-top: 14px;
          }
          .sig-card {
            border: 1px solid #cbd5e1;
            border-radius: 8px;
            padding: 8px 10px;
            background: #ffffff;
            height: 110px;
            vertical-align: top;
            width: 33.33%;
          }
          .sig-title {
            font-size: 9.5px;
            font-weight: 800;
            color: #0f766e;
            border-bottom: 1px dashed #cbd5e1;
            padding-bottom: 3px;
            margin-bottom: 5px;
          }
          .sig-name {
            font-size: 9.5px;
            color: #334155;
            font-weight: 600;
          }
          .sig-space {
            height: 44px;
            display: flex;
            align-items: center;
            justify-content: center;
          }
          .watermark-note {
            font-size: 8.5px;
            color: #94a3b8;
            text-align: center;
            margin-top: 10px;
            border-top: 1px solid #f1f5f9;
            padding-top: 5px;
          }
        </style>
      </head>
      <body>
        <!-- Header -->
        <table class="header-table">
          <tr>
            <td style="vertical-align: middle; width: 130px;">
              <img src="/logo_nesma.png?v=2" class="logo" alt="Nesma First Logo" />
            </td>
            <td style="vertical-align: middle; padding: 0 12px; text-align: ${isArabic ? 'right' : 'left'};">
              <div class="company-title">${compName}</div>
              <div class="company-sub">${isArabic ? `الرقم الموحد: ${compUnified} | الرقم الضريبي: ${compTax}` : `Unified No: ${compUnified} | VAT No: ${compTax}`}</div>
            </td>
            <td style="vertical-align: middle; text-align: ${isArabic ? 'left' : 'right'}; width: 160px;">
              <div class="order-title-box">
                <div class="order-title-ar">${isArabic ? 'أمر عمل' : 'WORK ORDER'}</div>
                <div class="order-title-en">${isArabic ? 'WORK ORDER' : 'أمر عمل'}</div>
              </div>
            </td>
          </tr>
        </table>

        <!-- Work Order Meta Grid -->
        <table class="order-meta-table">
          <tr>
            <td style="width: 35%;">
              <div class="meta-label">${isArabic ? 'رقم أمر العمل' : 'Work Order Ref'}</div>
              <div class="meta-value" style="font-family: monospace; font-size: 13px; color: #0f766e;">
                WO-#${quote.id.split('_')[1] || quote.id}
              </div>
              <div style="font-size: 9px; color: #64748b; margin-top: 2px;">
                ${isArabic ? 'مرجع عرض السعر:' : 'Ref Quote:'} #${quote.id.split('_')[1] || quote.id}
              </div>
            </td>
            <td style="width: 35%;">
              <div class="meta-label">${isArabic ? 'تاريخ التكليف والإصدار' : 'Issue & Assignment Date'}</div>
              <div class="meta-value">${issueAndAssignmentDate}</div>
              <div style="font-size: 9px; color: #64748b; margin-top: 2px;">
                ${isArabic ? 'تاريخ توجيه أمر العمل للفني' : 'Technician Dispatch Date'}
              </div>
            </td>
            <td style="width: 30%;">
              <div class="meta-label">${isArabic ? 'حالة أمر العمل' : 'Order Status'}</div>
              <div style="margin-top: 3px;">
                <span class="badge" style="background: ${statusBg}; color: ${statusColor}; border: 1px solid ${statusColor}33;">
                  ${statusLabel}
                </span>
              </div>
            </td>
          </tr>
          <tr>
            <td>
              <div class="meta-label">${isArabic ? 'العميل / المنشأة المستفيدة' : 'Client / Facility'}</div>
              <div class="meta-value">${quote.clientName}</div>
              <div style="font-size: 9.5px; color: #475569; margin-top: 2px;">
                ${isArabic ? 'الفرع / الموقع:' : 'Branch/Site:'} <strong>${branchName}</strong>
              </div>
              ${clientPhone ? `<div style="font-size: 9px; color: #475569;">${isArabic ? 'هاتف التواصل:' : 'Phone:'} <span style="font-family: monospace;">${clientPhone}</span></div>` : ''}
            </td>
            <td>
              <div class="meta-label">${isArabic ? 'موقع المنشأة والعنوان' : 'Facility Location & Address'}</div>
              <div class="meta-value" style="font-weight: 600;">${clientAddress}</div>
            </td>
            <td>
              <div class="meta-label">${isArabic ? 'الفني / الأخصائي المكلف' : 'Assigned Specialist'}</div>
              <div class="meta-value" style="color: #1e293b;">${assignedTechName}</div>
              ${assignedTechPhone ? `<div style="font-size: 9px; color: #64748b; margin-top: 2px;">${isArabic ? 'جوال الفني:' : 'Tech Mobile:'} ${assignedTechPhone}</div>` : ''}
            </td>
          </tr>
        </table>

        <!-- Section: Tasks / Scope of Work -->
        <div class="section-heading">
          <span>${isArabic ? '📋 بيان الأعمال والمهام وقطع الغيار المطلوبة' : '📋 Scope of Work, Items & Tasks'}</span>
        </div>

        <table class="tasks-table">
          <thead>
            <tr>
              <th style="width: 35px; text-align: center;">${isArabic ? 'م' : '#'}</th>
              <th style="text-align: ${isArabic ? 'right' : 'left'};">${isArabic ? 'بيان العمل / المهمة / قطع الغيار' : 'Task / Item Description'}</th>
              <th style="width: 75px; text-align: center;">${isArabic ? 'الكمية' : 'Qty'}</th>
              <th style="width: 110px; text-align: center;">${isArabic ? 'الضمان' : 'Warranty'}</th>
              <th style="width: 95px; text-align: center;">${isArabic ? 'حالة الإنجاز' : 'Status'}</th>
            </tr>
          </thead>
          <tbody>
            ${itemsRowsHtml}
          </tbody>
        </table>

        <!-- Section: Instructions & Guidelines -->
        <div class="section-heading">
          <span>${isArabic ? '🛡️ تعليمات التنفيذ والسلامة المهنية' : '🛡️ Execution & Safety Instructions'}</span>
        </div>
        <div class="instructions-box">
          <ul>
            <li>${isArabic ? 'الالتزام التام باشتراطات السلامة المهنية ومحددات الدفاع المدني السعودي أثناء العمل.' : 'Full compliance with occupational safety and Saudi Civil Defense standards during execution.'}</li>
            <li>${isArabic ? 'فحص واختبار الأنظمة والتأكد من جاهزيتها وخلوها من الأعطال بعد التركيب والتشغيل.' : 'Inspect and test all safety systems to ensure full operational readiness after work.'}</li>
            <li>${isArabic ? 'توثيق مراحل العمل بالصور والفيديو ورفع تقرير الإنجاز الفني لإدارة العمليات.' : 'Document work with photos and submit technical completion report to Operations.'}</li>
            <li>${isArabic ? 'أخذ توقيع وختم ممثل العميل / مسؤول الموقع في الخانة المخصصة أدناه عند انتهاء العمل.' : 'Obtain the client/site representative signature and stamp below upon completion.'}</li>
            ${specialNotes}
          </ul>
        </div>

        <!-- Section: Official Approvals & Signatures -->
        <div class="section-heading">
          <span>${isArabic ? '✍️ محضر الاستلام واعتمادات أمر العمل' : '✍️ Signatures & Work Order Verification'}</span>
        </div>

        <table class="signatures-table">
          <tr>
            <td class="sig-card">
              <div class="sig-title">${isArabic ? 'إدارة العمليات والمشاريع (المشرف)' : 'Operations Supervisor'}</div>
              <div class="sig-name">${isArabic ? 'معتمد للتنفيذ الميداني' : 'Approved for Execution'}</div>
              <div class="sig-space">
                ${COMPANY_STAMP_SVG}
              </div>
            </td>
            <td style="width: 10px;"></td>
            <td class="sig-card">
              <div class="sig-title">${isArabic ? 'الفني / الأخصائي المنفذ' : 'Assigned Technician'}</div>
              <div class="sig-name">${isArabic ? 'الاسم:' : 'Name:'} ${assignedTechName}</div>
              <div style="font-size: 8.5px; color: #64748b; margin-top: 3px;">${isArabic ? 'التوقيع والاستلام:' : 'Signature:'}</div>
              <div class="sig-space" style="border-bottom: 1px dotted #cbd5e1; height: 32px;"></div>
              <div style="font-size: 8px; color: #94a3b8; margin-top: 3px;">${isArabic ? 'التاريخ: .... / .... / ........' : 'Date: .... / .... / ........'}</div>
            </td>
            <td style="width: 10px;"></td>
            <td class="sig-card">
              <div class="sig-title">${isArabic ? 'العميل / مسؤول المنشأة والموقع' : 'Client / Site Supervisor'}</div>
              <div class="sig-name">${quote.clientName}</div>
              <div style="font-size: 8.5px; color: #64748b; margin-top: 3px;">${isArabic ? 'التوقيع والمصادقة على العمل:' : 'Signature & Acknowledgment:'}</div>
              <div class="sig-space" style="border-bottom: 1px dotted #cbd5e1; height: 32px;"></div>
              <div style="font-size: 8px; color: #94a3b8; margin-top: 3px;">${isArabic ? 'الختم / التاريخ: .... / .... / ........' : 'Stamp & Date: .... / .... / ........'}</div>
            </td>
          </tr>
        </table>

        <div class="watermark-note">
          ${isArabic 
            ? `${compName} - هذا المستند وثيقة عمل رسمية معتمدة للتشغيل الميداني`
            : `${compName} - Official Field Work Order Document`}
        </div>
      </body>
      </html>
    `;

    printHtmlContent(html);
  };



  const handleAssignTechnician = () => {
    if (!assigningWorkOrder) return;
    const tech = technicians.find(t => t.id === selectedAssigneeTechId);
    if (!tech) {
      alert(isRtl ? 'الرجاء اختيار الفني أولاً' : 'Please select a technician');
      return;
    }
    
    // Create updated quotation with the actual assignment date (تاريخ توجيه أمر العمل للفني)
    const assignmentDate = assigneeWorkOrderDate || new Date().toISOString().split('T')[0];
    const updatedQuote: Quotation = {
      ...assigningWorkOrder,
      assignedTechId: tech.id,
      assignedTechName: tech.name,
      workOrderStatus: 'pending', // Assigned & pending execution
      workOrderAssignedDate: assignmentDate
    };
    
    // Save/Update quotation
    onAddQuotation(updatedQuote);
    
    // Send SMS notification
    const msg = isRtl 
      ? `عزيزي الفني ${tech.name}، تم تكليفك بطلب عمل/صيانة جديد لصالح منشأة "${assigningWorkOrder.clientName}" (${assigningWorkOrder.branchName || 'الفرع الرئيسي'}). يرجى مراجعة البوابة لتفاصيل البنود والبدء بالصيانة.`
      : `Dear tech ${tech.name}, you have been assigned to a new work order for client "${assigningWorkOrder.clientName}". Please review your task lists in the app.`;
      
    if (tech.phone) {
      sendSMSNotification(tech.phone, tech.name, msg, 'technician_visit', assigningWorkOrder.clientName)
        .catch(err => console.error("Error sending SMS to tech:", err));
    }

    setShowAssignTechModal(false);
    setAssigningWorkOrder(null);
    alert(isRtl ? 'تم توجيه وتكليف الفني بنجاح بالعمل!' : 'Technician assigned successfully!');
  };

  const handleSaveQuotation = () => {
    if (!selectedClientForQuote) return;
    if (quoteItems.length === 0) {
      alert(isRtl ? 'يرجى إضافة بند واحد على الأقل في عرض السعر!' : 'Please add at least one item to the quotation!');
      return;
    }
    const subtotal = quoteItems.reduce((acc, curr) => acc + curr.totalPrice, 0);
    const dVal = quoteDiscountValue || 0;
    let discountAmount = 0;
    if (quoteDiscountType === 'percentage') {
      discountAmount = parseFloat(((subtotal * dVal) / 100).toFixed(2));
    } else {
      discountAmount = Math.max(0, parseFloat(dVal.toFixed(2)));
    }
    if (discountAmount > subtotal) discountAmount = subtotal;

    const taxableSubtotal = parseFloat((subtotal - discountAmount).toFixed(2));
    const vat = parseFloat((taxableSubtotal * 0.15).toFixed(2));
    const grandTotal = parseFloat((taxableSubtotal + vat).toFixed(2));
    
    // Find the original quotation if editing to merge and preserve other metadata like approval notes, payments, assigned techs, etc.
    const existingQuote = editingQuotationId ? quotations.find(q => q.id === editingQuotationId) : null;
    
    const newQuote: Quotation = {
      ...existingQuote, // Preserve existing properties
      id: editingQuotationId || `quote_${Date.now()}`,
      visitId: selectedVisitForQuote?.id || '',
      clientId: selectedClientForQuote.id,
      clientName: selectedClientForQuote.name,
      // Priority to the branch name if specified, then visit is linked to branch, otherwise fallback to standard client location/name
      branchName: selectedBranchName || selectedVisitForQuote?.branchName || selectedVisitForQuote?.branchId || (isRtl ? 'الفرع الرئيسي' : 'Main Branch'),
      date: quoteDate,
      items: quoteItems,
      subtotal,
      discountType: quoteDiscountType,
      discountValue: dVal,
      discountAmount,
      taxableSubtotal,
      vat,
      grandTotal,
      status: quoteStatus,
      terms: quoteTerms.trim()
    };

    onAddQuotation(newQuote);
    setShowCreateQuoteModal(false);
    setEditingQuotationId(null);
    alert(isRtl ? 'تم حفظ عرض السعر بنجاح، ويمكن للعميل الآن الاطلاع عليه عبر بوابته الخاصة!' : 'Quotation generated and saved successfully! The client can now review it in their portal.');
  };

