  const getDaysDiff = (expiryDateStr?: string) => {
    if (!expiryDateStr) return -999999;
    const expiryDate = new Date(expiryDateStr);
    const diffTime = expiryDate.getTime() - today.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

