  const handleStartRenewContract = (client: Client) => {
    setRenewingClient(client);
    setRenewContractNumber(client.contractNumber || '');
    
    // Calculate smart renewal start date:
    let calculatedStart = '';
    const todayStr = new Date().toISOString().split('T')[0];
    
    if (client.contractEndDate) {
      try {
        const prevEnd = new Date(client.contractEndDate);
        if (!isNaN(prevEnd.getTime())) {
          const nextDay = new Date(prevEnd);
          nextDay.setDate(nextDay.getDate() + 1);
          calculatedStart = nextDay.toISOString().split('T')[0];
        }
      } catch (e) {
        calculatedStart = todayStr;
      }
    }
    if (!calculatedStart) calculatedStart = todayStr;
    
    // End date defaults to 1 year later (minus 1 day)
    let calculatedEnd = '';
    try {
      const sDate = new Date(calculatedStart);
      const eDate = new Date(sDate);
      eDate.setFullYear(eDate.getFullYear() + 1);
      eDate.setDate(eDate.getDate() - 1);
      calculatedEnd = eDate.toISOString().split('T')[0];
    } catch (e) {
      calculatedEnd = '';
    }
    
    setRenewStartDate(calculatedStart);
    setRenewEndDate(calculatedEnd);
    setRenewFrequency(client.visitFrequency || '4');
    setRenewTechId(client.assignedTechnicianId || '');
    setRenewApplyToBranches(true);
    setRenewContractFile(null);
    setShowRenewContractModal(true);
  };

